static void file_warning(const char *filename, const char *fmt, ...) {
    if (!opt_no_warn && exit_status == 0) exit_status = 2;
    if (opt_verbosity < 0) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: %s: ", progname, filename);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}
