    }
    // Parse digits, check overflow
    uint64_t value = 0;
    bool overflow=false;
    const char *p=s;
    while (isdigit((unsigned char)*p)) {
        int d=*p-'0';
        if (value > (UINT64_MAX - d)/10) overflow=true;
        else value = value*10 + d;
        p++;
    }
    bool percent=false;
    uint64_t mult=1;
    if (allow_percent && *p=='%' && p[1]=='\0') {
