        const char *suf=p;
        // Map:
        struct { const char *s; uint64_t m; } table[] = {
            {"KiB", 1ULL<<10},{"MiB",1ULL<<20},{"GiB",1ULL<<30},
            {"KB",1ULL<<10},{"MB",1ULL<<20},{"GB",1ULL<<30},
            {"kB",1ULL<<10},{"mB",1ULL<<20},{"gB",1ULL<<30},
            {"K",1ULL<<10},{"M",1ULL<<20},{"G",1ULL<<30},
            {"k",1ULL<<10},{"m",1ULL<<20},{"g",1ULL<<30},
            {NULL,0}
        };
        bool found=false;
        for (int i=0;table[i].s;i++) if (strcmp(suf, table[i].s)==0) { mult=table[i].m; found=true; break; }
