        }
    }
    if (percent) {
        // Range for percent is 1-100, option name in message is e.g. 'memlimit%' (optname + %)
        if (overflow || value < 1 || value > 100) {
            char buf[128]; snprintf(buf,sizeof buf,"%s%%", optname);
            fatal_range(buf, 1, 100);
