static uint64_t parse_size_or_int(const char *str, const char *optname, uint64_t minv, uint64_t maxv, bool allow_suffix, bool allow_percent) {
    // skip leading spaces? Observed for memlimit "  1MiB" ok. What about internal? We'll skip isspace at start.
    const char *s = str;
