        // For empty, prints ": ..."
        msg_fatal_exit("%s: Value is not a non-negative decimal integer", str);
    }
    // Parse digits, check overflow
    uint64_t value = 0;
    bool overflow=false;
    const char *p=s;
    while (isdigit((unsigned char)*p)) {
        int d=*p-'0';
        if (value > (UINT64_MAX - d)/10) overflow=true;
