            opts->lc = (uint32_t)parse_uint_opt(value, "lc", LZMA_LCLP_MIN, LZMA_LCLP_MAX);
        } else if (strcmp(name,"lp")==0) {
            opts->lp = (uint32_t)parse_uint_opt(value, "lp", LZMA_LCLP_MIN, LZMA_LCLP_MAX);
        } else if (strcmp(name,"pb")==0) {
            opts->pb = (uint32_t)parse_uint_opt(value, "pb", LZMA_PB_MIN, LZMA_PB_MAX);
        } else if (strcmp(name,"mode")==0) {
            if (strcmp(value,"fast")==0) opts->mode=LZMA_MODE_FAST;
            else if (strcmp(value,"normal")==0) opts->mode=LZMA_MODE_NORMAL;
            else msg_fatal_exit("%s: Invalid option value", value);
        } else if (strcmp(name,"nice")==0) {
            opts->nice_len = (uint32_t)parse_uint_opt(value, "nice", 2, 273);
        } else if (strcmp(name,"mf")==0) {
            if (strcmp(value,"hc3")==0) opts->mf=LZMA_MF_HC3;
            else if (strcmp(value,"hc4")==0) opts->mf=LZMA_MF_HC4;
            else if (strcmp(value,"bt2")==0) opts->mf=LZMA_MF_BT2;
            else if (strcmp(value,"bt3")==0) opts->mf=LZMA_MF_BT3;
            else if (strcmp(value,"bt4")==0) opts->mf=LZMA_MF_BT4;
            else msg_fatal_exit("%s: Invalid option value", value);
        } else if (strcmp(name,"depth")==0) {
            opts->depth = (uint32_t)parse_uint_opt(value, "depth", 0, UINT32_MAX);
        } else {
            msg_fatal_exit("%s: Invalid option name", name);
        }
        // lc+lp check: Do immediate? Probe later. We'll defer to end of whole string below.
