static void parse_bcj_opts_old(const char *str, lzma_options_bcj *opts) {
    if (!str || !str[0]) return;
    char *copy=xstrdup(str); char *save=NULL;
    for (char *token=strtok_r(copy,",",&save); token; token=strtok_r(NULL,",",&save)) {
        char *eq=strchr(token,'=');
        if (!eq || eq==token || eq[1]=='\0') msg_fatal_exit("%s: Options must be 'name=value' pairs separated with commas", token);
        *eq='\0';
        if (strcmp(token,"start")!=0) msg_fatal_exit("%s: Invalid option name", token);
        opts->start_offset = (uint32_t)parse_uint_opt(eq+1,"start",0,UINT32_MAX);
    }
    free(copy);
}
static void parse_delta_opts_old(const char *str, lzma_options_delta *opts) {
    if (!str || !str[0]) return;
    char *copy=xstrdup(str); char *save=NULL;
    for (char *token=strtok_r(copy,",",&save); token; token=strtok_r(NULL,",",&save)) {
        char *eq=strchr(token,'=');
        if (!eq || eq==token || eq[1]=='\0') msg_fatal_exit("%s: Options must be 'name=value' pairs separated with commas", token);
        *eq='\0';
        if (strcmp(token,"dist")!=0) msg_fatal_exit("%s: Invalid option name", token);
        opts->dist = (uint32_t)parse_uint_opt(eq+1,"dist",LZMA_DELTA_DIST_MIN,LZMA_DELTA_DIST_MAX);
    }
    free(copy);
}

// Add a filter via old-style option to chain0.
// State machine: If chain0 currently is preset OR spec_is_string (last was --filters), then starting a new old-style chain: clear chain0, count=0.
// Then append filter. If count would exceed 4 -> fatal "Maximum number of filters is four" (message observed: no period)
// Note: initial default preset counts as not spec, so first old-style clears preset.
// After adding, chain0_have_spec=true; chain0_spec_is_string=false; is_preset=false.
static void add_oldstyle_filter(lzma_vli id, const char *optstr) {
    if (!chain0_have_spec || chain0_spec_is_string) {
        chain_clear(&chains[0]);
        chains[0].is_set=true;
        chain0_have_spec=true;
        chain0_spec_is_string=false;
        chain0_is_preset=false;
        chains[0].is_preset=false;
    }
    if (chains[0].count >= 4) {
        msg_fatal_exit("Maximum number of filters is four");
    }
    int idx = chains[0].count;
    chains[0].filters[idx].id=id;
    void *opts=NULL;
    if (id==LZMA_FILTER_LZMA1 || id==LZMA_FILTER_LZMA2) {
        lzma_options_lzma *o = new_lzma_opts_preset(6); // default preset 6 without extreme? Observations: --lzma2=dict=2MiB alone gave preset6 base (mode normal nice64). If -e or -1 earlier, they get cleared by starting new chain, so base is 6 not current preset. What about adding second filter after delta: --delta --lzma2=dict=... base 6 also.
        // However, if user includes preset= in optstring, parse will reset.
        parse_lzma_opts_old(optstr, o);
        opts=o;
    } else if (id==LZMA_FILTER_DELTA) {
        lzma_options_delta *o=new_delta_opts(1);
        parse_delta_opts_old(optstr,o);
        opts=o;
    } else {
        lzma_options_bcj *o=new_bcj_opts(0);
        parse_bcj_opts_old(optstr,o);
        opts=o;
    }
    chains[0].filters[idx].options=opts;
    chains[0].count++;
    chains[0].filters[chains[0].count].id=LZMA_VLI_UNKNOWN;
    chains[0].filters[chains[0].count].options=NULL;
}

// Set preset on chain0 ( -0..-9, -e )
static void set_preset_chain0(void) {
    uint32_t pr = opt_preset | (opt_extreme ? LZMA_PRESET_EXTREME : 0);
    chain_set_preset(&chains[0], pr, false);
    chains[0].is_preset=true;
    chain0_have_spec=false;
    chain0_spec_is_string=false;
    chain0_is_preset=true;
}

