// On error exit via filters_error_exit with proper pos/msg.
// Returns value (after multiplier). Also validates range by caller -> Value out of range at value_start.
static uint64_t filters_parse_number(filters_parser *prs, size_t val_start, const char *val, size_t len) {
    if (len==0) filters_error_exit(prs, val_start, "Option value cannot be empty");
    if (!isdigit((unsigned char)val[0])) filters_error_exit(prs, val_start, "Value is not a non-negative decimal integer");
