    if (opt_filenames_count >= opt_filenames_cap) {
        opt_filenames_cap = opt_filenames_cap?opt_filenames_cap*2:16;
        opt_filenames = xrealloc(opt_filenames, opt_filenames_cap*sizeof(char*));
