// For --files with no arg (stdin): read filenames from stdin during parse. If stdin is also used as an input file "-" in list, that gave error "-: No such file" (treated literally). Also reading stdin list consumes stdin.
// Storage for file list sources during parse:
typedef struct { char *filename; bool is_zero; bool from_stdin; } files_source;
static files_source *files_sources=NULL;
static size_t files_sources_count=0, files_sources_cap=0;
static void add_files_source(const char *filename, bool is_zero) {
    if (files_sources_count>=files_sources_cap){ files_sources_cap=files_sources_cap?files_sources_cap*2:8; files_sources=xrealloc(files_sources, files_sources_cap*sizeof(files_source)); }
    files_sources[files_sources_count].filename = filename?xstrdup(filename):NULL;
    files_sources[files_sources_count].is_zero=is_zero;
    files_sources[files_sources_count].from_stdin = (filename==NULL);
    files_sources_count++;
}
static void read_files_sources(void) {
    for (size_t s=0;s<files_sources_count;s++) {
        FILE *f;
        const char *dispname;
        if (files_sources[s].from_stdin) { f=stdin; dispname="(stdin)"; }
        else {
            f=fopen(files_sources[s].filename,"r");
            dispname=files_sources[s].filename;
