                file_error(dispname, "%s", strerror(errno));
                exit(1);
            }
        }
        int delim = files_sources[s].is_zero ? '\0' : '\n';
        // Read entire stream split by delim. Filenames: empty entries skipped? Observation: empty lines skipped (but what about a line with spaces? treated as name "  "?).
        // Also last entry without terminator? probably included if non-empty.
        // Use dynamic buffer per entry.
        size_t cap=256,len=0; char *buf=xmalloc(cap);
        int c;
        bool any_data=false;
        while ((c=fgetc(f))!=EOF) {
            any_data=true;
            if (c==delim) {
                if (len>0) { buf[len]='\0'; add_filename(buf); len=0; }
