// Generic streaming encode loop using an initialized lzma_stream.
// Handles reading input, block full-flushes for ST xz with block_size/block_list_same_chain, writing output.
// If manual preprocessing is needed for raw format, caller will have handled whole-buffer path before this.
static bool encode_stream_loop(io_pair *pair, lzma_stream *strm, bool is_xz_st) {
    uint8_t inbuf[IO_BUF_SIZE];
    uint8_t outbuf[IO_BUF_SIZE];
    // Block flush tracking for ST xz
    uint64_t block_remaining = 0;
    // Determine next block size: if block_list (same chain case only called when all entries use chain0 or format?) For now this function is not used for block_list with different chains.
    bool use_block_flush = false;
    uint64_t next_block_size = 0;
    size_t block_list_idx=0;
    if (is_xz_st) {
        if (opt_block_list_len>0) {
            use_block_flush=true;
            next_block_size=opt_block_list[0].size;
            block_list_idx=0;
        } else if (opt_block_size_set && opt_block_size!=0) {
            use_block_flush=true;
            next_block_size=opt_block_size;
        }
    }
    block_remaining = next_block_size; // 0 means no limit in block-list semantics (rest)
    bool eof=false;
    lzma_action action=LZMA_RUN;
    strm->avail_in=0;
    strm->next_in=NULL;
    while (true) {
        // Fill input if needed and not doing a flush operation
        if (strm->avail_in==0 && !eof && action==LZMA_RUN) {
            size_t to_read=sizeof inbuf;
            // To implement flush timeout sync flush, we'd need nonblocking read magic. Ignore.
            size_t n=fread(inbuf,1,to_read,pair->src_fp);
            if (n==0) {
                if (feof(pair->src_fp)) {
                    eof=true;
                    action=LZMA_FINISH;
                } else if (ferror(pair->src_fp)) {
                    read_error_msg(pair, errno);
                    return false;
                }
            } else {
                pair->bytes_in += n; // counts uncompressed input read (for verbose) - Note if encoder hasn't consumed yet, at error this may overcount but verbose not printed on error.
                strm->next_in=inbuf;
                strm->avail_in=n;
                // If we are at a block boundary and there is more data, we should have done full flush before feeding this new data. Handle below before calling code with new data.
            }
        }
        // Block flush initiation: if ST and use_block_flush and block_remaining==0 and not eof and we have input waiting, start FULL_FLUSH with no input.
        // But our block_remaining tracking counts bytes *consumed by encoder* (strm total_in changes). We need track consumed rather than read.
        // Simpler detection: maintain consumed_in_current_block based on strm->total_in delta each loop. We'll compute at bottom.
        // This loop structure is getting complex; alternative model:
        // We feed input in chunks limited to block_remaining (so avail_in never exceeds remaining). When remaining reaches 0 and encoder consumed all, we peek if there's more input: try read next chunk (store in a peek buffer). If EOF, finish normally; if more, do FULL_FLUSH (calling code with avail_in=0 action=FULL_FLUSH until STREAM_END), then start next block.
        // Implementing that nested model would be cleaner to rewrite loop. For initial implementation, we will handle block flushing by limiting avail_in per code call and handling flush state with variables.
        // Rework: Use state variables flush_needed (bool)
        // Given complexity, we will implement a separate loop below in a replacement function if use_block_flush.
        break; // placeholder - actual implementation will be encode_stream_loop_impl
    }
    (void)outbuf; (void)block_list_idx; (void)eof; (void)action;
    return true;
}
CEOF
