static bool encode_with_stream(io_pair *pair, lzma_stream *strm, bool is_xz_and_can_fullflush) {
    uint8_t inbuf[IO_BUF_SIZE];
    uint8_t outbuf[IO_BUF_SIZE];
    // Block boundary tracking for single-thread xz full-flush mode
    bool use_blocks = false;
    uint64_t block_limit = 0; // 0 = unlimited for current block
