        if (opt_block_list_len > 0) {
            use_blocks = true;
            block_limit = opt_block_list[0].size;
            bl_idx = 0;
        } else if (opt_block_size_set && opt_block_size != 0) {
            use_blocks = true;
            block_limit = opt_block_size;
        }
    }
    uint64_t in_block = 0; // uncompressed bytes consumed by encoder in current block
    uint64_t last_total_in = 0;
    bool eof = false;
    bool flushing = false; // performing FULL_FLUSH
    strm->next_in = NULL;
    strm->avail_in = 0;
    while (true) {
        // If not flushing and no input available and not eof, read more.
        if (!flushing && strm->avail_in == 0 && !eof) {
            // If a block limit has been reached and we've consumed all input,
            // peek/read next chunk to decide whether flush is needed.
            // Read into inbuf.
            size_t n = fread(inbuf, 1, sizeof inbuf, pair->src_fp);
            if (n == 0) {
                if (feof(pair->src_fp)) {
                    eof = true;
                } else {
                    read_error_msg(pair, errno ? errno : EIO);
                    return false;
                }
            } else {
                pair->bytes_in += n;
                strm->next_in = inbuf;
                strm->avail_in = n;
                // If block limit reached before this new data, we need to
                // full-flush the previous block first, holding this input.
                if (use_blocks && block_limit != 0 && in_block >= block_limit) {
                    flushing = true;
                    // Temporarily set avail_in to 0 for flush calls, but
                    // remember pending input in inbuf (next_in/avail stored)
                    // We'll keep pending variables:
                    // To simplify, we perform flush inline here with a
                    // separate avail_in shadow.
                    // Save pending:
                    const uint8_t *pending_in = strm->next_in;
                    size_t pending_avail = strm->avail_in;
                    strm->next_in = NULL;
                    strm->avail_in = 0;
                    // Flush loop
                    while (true) {
                        strm->next_out = outbuf;
                        strm->avail_out = sizeof outbuf;
                        lzma_ret ret = lzma_code(strm, LZMA_FULL_FLUSH);
                        size_t out_size = sizeof outbuf - strm->avail_out;
                        if (out_size > 0) {
                            if (!io_write(pair, outbuf, out_size)) { write_error_msg(pair, errno); return false; }
                        }
                        if (ret == LZMA_STREAM_END) break;
                        if (ret != LZMA_OK) { coder_handle_error(pair, ret, strm, true); return false; }
                    }
                    // Start next block: advance block-list if needed
                    if (opt_block_list_len > 0) {
                        if (bl_idx + 1 < opt_block_list_len) bl_idx++;
                        block_limit = opt_block_list[bl_idx].size;
                        // Filter chain changes are NOT supported in this
                        // path (caller routes multi-chain block-lists elsewhere)
                    }
                    in_block = 0;
                    last_total_in = strm->total_in;
                    // Restore pending input
                    strm->next_in = (uint8_t*)pending_in;
                    strm->avail_in = pending_avail;
                    flushing = false;
                    // If new block_limit == 0, no more flushing needed.
                }
            }
