            // strm->next_in has advanced by consumed. Total pending should be
            // (saved_avail - consumed). avail_in field currently is limited_remaining.
            size_t limited_before = (size_t)((block_limit > in_block) ? (block_limit - in_block) : 0);
            if (limited_before > saved_avail) limited_before = saved_avail;
            consumed = limited_before - strm->avail_in;
            strm->avail_in = saved_avail - consumed;
            // next_in already points to correct position
        }
        size_t out_size = sizeof outbuf - strm->avail_out;
        if (out_size > 0) {
            if (!io_write(pair, outbuf, out_size)) { write_error_msg(pair, errno); return false; }
        }
        // Update in_block from total_in delta
        uint64_t delta_in = strm->total_in - last_total_in;
        // total_in for encoders counts uncompressed input consumed - good.
        // But during flush above we reset last_total_in.
        in_block += delta_in;
        last_total_in = strm->total_in;
        if (ret == LZMA_STREAM_END) {
            // Finished (for FINISH)
            break;
        }
        if (ret != LZMA_OK) {
            coder_handle_error(pair, ret, strm, true);
            return false;
        }
        // If eof and avail_in==0 and avail_out==0, continue loop to finish.
        // If we are at block boundary and encoder has consumed all input
        // we have (avail_in==0) and not eof, next iteration will read more
        // and decide to flush.
        // Prevent busy loop when encoder consumed nothing and produced nothing but is waiting for more input/output - normal loop will read.
    }
    return true;
}

