static size_t vli_encode_len(uint64_t v){ size_t n=1; while(v>=0x80){v>>=7;n++;} return n; }
static size_t vli_encode_to(uint64_t v, uint8_t *out){ size_t n=0; do{ uint8_t b=v&0x7F; v>>=7; if(v) b|=0x80; out[n++]=b; }while(v); return n; }
