static bool vli_decode_from(const uint8_t *buf, size_t size, size_t *pos, uint64_t *out){
    uint64_t val=0; int shift=0; size_t i=*pos;
    while(true){
        if(i>=size) return false;
        uint8_t b=buf[i++];
        if(shift==63) return false; // too long
