static uint32_t parse_lzma2_dict_from_prop(uint8_t prop){
    // From xz spec decode
    uint8_t bits=prop & 0x3F;
    if(bits>40) return 0;
    if(bits==40) return UINT32_MAX;
    uint32_t sz = 2 | (bits & 1);
    sz <<= bits/2 + 11;
    return sz;
}
static bool encode_lzma2_dict_prop(uint32_t dict, uint8_t *out){
    // Find bits such that decoded size >= dict and minimal. Encoder in lib will round up dict to this decoded size - actual dict used might be user size, but header encodes rounded up.
    for(int bits=0;bits<=40;bits++){ uint32_t sz; if(bits==40) sz=UINT32_MAX; else { sz=2|(bits&1); sz<<=bits/2+11; } if(sz>=dict){*out=(uint8_t)bits; return true;} }
    return false;
}
// Decode filter properties for one filter into options struct (allocated). Returns false on invalid props size/content (should map to OPTIONS/DATA error depending caller)
static void *decode_filter_props(lzma_vli id, const uint8_t *props, size_t props_size, bool *ok){
    *ok=true;
    if(id==LZMA_FILTER_LZMA1){
        if(props_size!=5){*ok=false;return NULL;}
        lzma_options_lzma *o=new_lzma_opts_preset(6);
        uint8_t p=props[0];
        if(p>225){free(o);*ok=false;return NULL;}
        o->pb=p/(9*5); p-=o->pb*9*5; o->lp=p/9; o->lc=p - o->lp*9;
        o->dict_size=(uint32_t)props[1]|((uint32_t)props[2]<<8)|((uint32_t)props[3]<<16)|((uint32_t)props[4]<<24);
