        if(o->dict_size < LZMA_DICT_SIZE_MIN) o->dict_size=LZMA_DICT_SIZE_MIN;
        return o;
    } else if(id==LZMA_FILTER_LZMA2){
        if(props_size!=1){*ok=false;return NULL;}
        lzma_options_lzma *o=new_lzma_opts_preset(6);
        if(props[0]>40){free(o);*ok=false;return NULL;}
        // High bits of prop must be zero (?) bits 6-7 reserved, if set options error
        if(props[0] & 0xC0){free(o);*ok=false;return NULL;}
        o->dict_size=parse_lzma2_dict_from_prop(props[0]);
        return o;
    } else if(id==LZMA_FILTER_DELTA){
        if(props_size!=1){*ok=false;return NULL;}
        return new_delta_opts((uint32_t)props[0]+1);
    } else if(id==LZMA_FILTER_X86||id==LZMA_FILTER_POWERPC||id==LZMA_FILTER_IA64||id==LZMA_FILTER_ARM||id==LZMA_FILTER_ARMTHUMB||id==LZMA_FILTER_SPARC||id==LZMA_FILTER_ARM64||id==LZMA_FILTER_RISCV){
        if(props_size==0) return new_bcj_opts(0);
        if(props_size!=4){*ok=false;return NULL;}
        uint32_t start=read_le32(props);
        return new_bcj_opts(start);
    }
    *ok=false; return NULL;
}
static size_t encode_filter_props(const lzma_filter *f, uint8_t *out, bool *ok){
    *ok=true;
    if(f->id==LZMA_FILTER_LZMA1){
        lzma_options_lzma *o=f->options; if(!o){*ok=false;return 0;}
        out[0]=(uint8_t)((o->pb*5+o->lp)*9+o->lc);
        // dict size stored as-is (?) For .xz block filter props, LZMA1 cannot be in xz, only raw/lzma fmt not block. Not used in xz custom.
        write_le32(out+1,o->dict_size);
        return 5;
    } else if(f->id==LZMA_FILTER_LZMA2){
        lzma_options_lzma *o=f->options; if(!o){*ok=false;return 0;}
        if(!encode_lzma2_dict_prop(o->dict_size,out)){*ok=false;return 0;}
        return 1;
    } else if(f->id==LZMA_FILTER_DELTA){
        lzma_options_delta *o=f->options; out[0]=(uint8_t)((o?o->dist:1)-1); return 1;
    } else {
        lzma_options_bcj *o=f->options; uint32_t start=o?o->start_offset:0;
        if(start==0) return 0;
        write_le32(out,start); return 4;
    }
}
// Filter flags size (ID vli + size vli + props)
static size_t filter_flags_encoded_size(const lzma_filter *f){
    uint8_t tmp[32]; bool ok; size_t props_size=encode_filter_props(f,tmp,&ok); if(!ok) return 0;
    return vli_encode_len(f->id)+vli_encode_len(props_size)+props_size;
}
