            if(csz>0){
                fseeko(fp,(off_t)check_offset,SEEK_SET);
                if(fread(bi->check_value,1,csz,fp)!=csz){free_parsed_block_header(&bh); fclose(fp); fi->parse_error=true; fi->error_msg=xstrdup("Compressed data is corrupt"); return 1;}
            }
            free_parsed_block_header(&bh);
        }
        if(fi->blocks_count==0){
            // min version still 50000002, memneeded 0, all_headers have sizes remains true (reference said Yes)
        }
    } else {
        // For non-vv, does list check something about block headers to determine ... No.
    }
    fclose(fp);
    return 0;
}
